# Surah Yusuf (chapter 12) — part 2: ayat 11-20 (IDs 1607-1616)
SURAH = 12

ENTRIES = {
1607: (
"انہوں نے کہا — اے ہمارے ابا — آپ کو کیا ہو گیا — کہ — آپؑ — ہمیں — یوسفؑ پر بھروسہ — نہیں کرتے — حالانکہ — ہم — اس کے — خیرخواہ — ہیں",
"""۱۔ بھائی — باپ کو — یوسفؑ کی حفاظت کا — یقین دلا دیتے ہیں۔
۲۔ ’’قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنُّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ‘‘ — انہوں نے کہا — اے ہمارے ابا — آپ کو کیا ہو گیا — کہ — آپؑ — ہمیں — یوسفؑ پر بھروسہ — نہیں کرتے — حالانکہ — ہم — اس کے — خیرخواہ — ہیں — یعنی جب — انہوں نے کہا — اے ہمارے ابا — آپ کو کیا — ہو گیا — کہ آپؑ ہم پر یوسف کی حفاظت — کا — بھروسہ — نہیں کرتے — حالانکہ ہم اس کے خیرخواہ — ہیں۔
۳۔ عملی سبق: اعتماد — جتلانا — اکثر — دھوکے — کا — طریقہ ہوتا ہے۔"""
),
1608: (
"اسے — کل — ہمارے ساتھ — بھیجیں — تاکہ — وہ — چرے — اور کھیلے — اور — ہم — اس — کے — محافظ — ہیں",
"""۱۔ بھائی — یوسفؑ — کو گوشت — کے لیے — باہر لے جانے کا تقاضا۔
۲۔ ’’أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ‘‘ — اسے — کل — ہمارے ساتھ — بھیجیں — تاکہ — وہ — چرے — اور کھیلے — اور — ہم — اس — کے — محافظ — ہیں — یعنی کل اسے — ہمارے ساتھ — بھیجیں — تاکہ وہ چرے — اور کھیلے — اور — ہم اس کے محافظ — ہیں۔
۳۔ عملی سبق: وعدے — آسان — ہوتے ہیں؛ ان سے زیادہ — اہتمام — ضروری ہے۔"""
),
1609: (
"انہوں نے کہا — بے شک — مجھے یہ بات — غمگین — کرتی — ہے کہ تم — اسے — لے — جاؤ — اور — میں ڈرتا ہوں — کہ — اسے — بھیڑیا — کھا — جائے — اور — تم — اس — سے — بے خبر — ہو",
"""۱۔ یعقوبؑ — اسے لے جانے سے غم اور الذئب کے ڈر کا اظہار۔
۲۔ ’’قَالَ إِنِّي لَيَحْزُنُنِي أَن تَذْهَبُوا بِهِ وَأَخَافُ أَن يَأْكُلَهُ الذِّئْبُ وَأَنتُمْ عَنْهُ غَافِلُونَ‘‘ — انہوں نے کہا — بے شک — مجھے یہ بات — غمگین — کرتی — ہے کہ تم — اسے — لے — جاؤ — اور — میں ڈرتا ہوں — کہ — اسے — بھیڑیا — کھا — جائے — اور — تم — اس — سے — بے خبر — ہو — یعنی یعقوبؑ — نے کہا — بے شک — مجھے یہ بات — غمگین — کرتی ہے کہ تم — اسے — لے جاؤ — اور — میں ڈرتا ہوں — کہ — اسے بھیڑیا — کھا — جائے — اور — تم — اس — سے — بے خبر — ہو۔
۳۔ عملی سبق: والدین کے خدشات — نفرت — کی وجہ — نہیں؛ محبت — کی بنیاد ہیں۔"""
),
1610: (
"انہوں نے کہا — اگر — اسے بھیڑیا کھا گیا — اور — ہم — ایک — جماعت — ہیں — تو — ہم — اس — صورت — میں خسارے — میں ہیں",
"""۱۔ بھائی — بھیڑیا کے واقعے — سے — باپ کا غم — ختم — کرنے کی کوشش۔
۲۔ ’’قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَۃٌ إِنَّا إِذًا لَّخَاسِرُونَ‘‘ — انہوں نے کہا — اگر — اسے بھیڑیا کھا گیا — اور — ہم — ایک — جماعت — ہیں — تو — ہم — اس — صورت — میں خسارے — میں ہیں — یعنی انہوں نے کہا — اگر — اسے بھیڑیا — کھا جائے — اور — ہم — ایک طاقت — ور جماعت — میں — ہیں — تو ہم — اس — صورت — میں — خسارے — میں — ہیں۔
۳۔ عملی سبق: جھوٹی وابستگیاں — جھوٹ — کی جانب — دھکیلتی ہیں۔"""
),
1611: (
"پس — جب — وہ — اسے — لے گئے — اور — انہوں نے — اسے — کنویں — کی اندھیری — جگہ — میں — ڈالنے — کا فیصلہ کر لیا — اور — ہم — نے — اسے — وحی کی — کہ — تم — عنقریب — ان — کو — اس — عمل — کی خبر — دو گے — اور — وہ — شعور نہیں — رکھتے",
"""۱۔ یوسفؑ — کنویں میں؛ اللہ کی طرف سے — وحی — کہ — وہ — عنقریب — بھائیوں — کو — خبر — دیں گے۔
۲۔ ’’فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَن يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ‘‘ — پس — جب — وہ — اسے — لے گئے — اور — انہوں نے — اسے — کنویں — کی اندھیری — جگہ — میں — ڈالنے — کا فیصلہ کر لیا — اور — ہم — نے — اسے — وحی کی — کہ — تم — عنقریب — ان — کو — اس — عمل — کی خبر — دو گے — اور — وہ — شعور نہیں — رکھتے — یعنی جب — وہ — اسے — لے گئے — اور — انہوں نے — اسے کنویں کی — اندھیری جگہ — میں ڈالنے کا — فیصلہ — کیا — اور — ہم — نے — اسے — وحی کی — تم عنقریب — ان — کو — اس — عمل — کی خبر — دو گے — اور وہ — شعور — نہیں رکھتے۔
۳۔ عملی سبق: اللہ — اپنے اولیاء — کی حفاظت — خود کرتا ہے؛ خوف — کی کوئی ضرورت نہیں۔"""
),
1612: (
"اور — وہ — اپنے — باپ — کے پاس — رات — کو — روتا — ہوا — آیا",
"""۱۔ بھائی — مصنوعی — غم کے ساتھ — والد — کے پاس آتے ہیں۔
۲۔ ’’وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ‘‘ — اور — وہ — اپنے — باپ — کے پاس — رات — کو — روتا — ہوا — آیا — یعنی وہ — رات — کو — روتا ہوا — اپنے — باپ — کے پاس — آئے۔
۳۔ عملی سبق: جھوٹا — دکھ — عین — سازش — ہے؛ شیطانی — راہ — ہے۔"""
),
1613: (
"انہوں نے کہا — اے — ہمارے ابا — ہم — دوڑ — میں — ہونے کے لیے — گئے تھے — اور — ہم نے — یوسف — کو — اپنے سامان — کے — پاس — چھوڑ دیا — تو — اسے — بھیڑیا — کھا گیا — اور — آپؑ — ہمیں — یقین — نہیں — کریں گے — اگرچہ — ہم سچے — ہوں",
"""۱۔ بھائی — مصنوعی — روتے ہوئے — جھوٹ — بنا کر — باپ کو — یقین — دلاتے ہیں۔
۲۔ ’’قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَادِقِينَ‘‘ — انہوں نے کہا — اے — ہمارے ابا — ہم — دوڑ — میں — ہونے کے لیے — گئے تھے — اور — ہم نے — یوسف — کو — اپنے سامان — کے — پاس — چھوڑ دیا — تو — اسے — بھیڑیا — کھا گیا — اور — آپؑ — ہمیں — یقین — نہیں — کریں گے — اگرچہ — ہم سچے — ہوں — یعنی انہوں نے کہا — اے ہمارے ابا — ہم — دوڑ — میں — گئے — اور — ہم — نے یوسفؑ — کو — اپنے سامان — کے پاس — چھوڑ دیا — تو — اسے — بھیڑیا — کھا گیا — اور آپؑ — ہمیں — یقین — نہیں کریں گے — اگرچہ ہم سچے — ہوں۔
۳۔ عملی سبق: جھوٹ — اکثر — ایک — ہی — جہت میں ہوتا ہے؛ سچائی — وقت پر — ظاہر — ہوتی ہے۔"""
),
1614: (
"اور — وہ — اس کے — کرتے پر — جھوٹا — خون — لائے — انہوں نے کہا — بلکہ — تمہارے نفسوں — نے — تمہارے لیے — ایک — معاملہ — اچھی طرح — سجایا — پس — صبر — جمیل — ہے — اور — اللہ — اس چیز — پر — مددگار — ہے — جو — تم — بیان — کرتے ہو",
"""۱۔ جھوٹا — خون — سے — باپ کو — دھوکہ دینے کی کوشش؛ یعقوبؑ صبر — جمیل — کا اعلان۔
۲۔ ’’وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ‘‘ — اور — وہ — اس کے — کرتے پر — جھوٹا — خون — لائے — انہوں نے کہا — بلکہ — تمہارے نفسوں — نے — تمہارے لیے — ایک — معاملہ — اچھی طرح — سجایا — پس — صبر — جمیل — ہے — اور — اللہ — اس چیز — پر — مددگار — ہے — جو — تم — بیان — کرتے ہو — یعنی وہ — اس کے — کرتے — پر جھوٹا — خون — لائے — یعقوبؑ نے کہا — بلکہ — تمہارے — نفسوں — نے — تمہارے لیے — ایک — معاملہ — سجایا — پس صبر — جمیل — کرنا ہے — اور — اللہ — اس — چیز — پر — مددگار — ہے — جو — تم — بیان — کرتے ہو۔
۳۔ عملی سبق: جھوٹ کے ثبوت — اکثر — شک — میں ہوتے ہیں؛ صبر — جمیل — بہترین — جواب ہے۔"""
),
1615: (
"اور — ایسے ہی قافلہ — آیا — انہوں نے — اپنا — پانی لانے والا — بھیجا — تو — اس — نے — اپنا — ڈول — نیچے کر دیا — اس — نے — کہا — اے — خوشخبری — یہ — ایک — لڑکا — ہے — اور — انہوں — نے — اس — کو — بطور مال تجارت — چھپایا — اور — اللہ — ان — کے — اعمال — سے — باخبر — ہے",
"""۱۔ قافلے — کو — یوسفؑ — کنواں — میں ملے؛ خوشخبری کا اعلان۔
۲۔ ’’وَجَاءَتْ سَيَّارَۃٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَۃً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ‘‘ — اور — ایسے ہی قافلہ — آیا — انہوں نے — اپنا — پانی لانے والا — بھیجا — تو — اس — نے — اپنا — ڈول — نیچے کر دیا — اس — نے — کہا — اے — خوشخبری — یہ — ایک — لڑکا — ہے — اور — انہوں — نے — اس — کو — بطور مال تجارت — چھپایا — اور — اللہ — ان — کے — اعمال — سے — باخبر — ہے — یعنی ایک — قافلہ آیا — انہوں — نے اپنا پانی لانے والا — بھیجا — تو — اس — نے اپنا — ڈول — نیچے کر دیا — اس — نے کہا — اے — خوشخبری — یہ — ایک — لڑکا — ہے — اور — انہوں — نے — اسے — بطور — مال تجارت — چھپایا — اور — اللہ — ان کے — اعمال — سے باخبر — ہے۔
۳۔ عملی سبق: یوسفؑ — کی — حفاظت — ایک — عظیم — امتحان — کی — منزلیں — ہیں۔"""
),
1616: (
"اور — انہوں — نے — اسے — کم — قیمت — پر — بیچ — دیا — گنتی — کے درہموں — پر — اور — وہ — اس — میں — سے — بے رغبت — تھے",
"""۱۔ یوسفؑ — کو — سستے — داموں — بیچا گیا — بھائی — اس سے بے رغبت۔
۲۔ ’’وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَۃٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ‘‘ — اور — انہوں — نے — اسے — کم — قیمت — پر — بیچ — دیا — گنتی — کے درہموں — پر — اور — وہ — اس — میں — سے — بے رغبت — تھے — یعنی انہوں نے — اسے — کم قیمت — پر — گنتی — کے درہموں — میں — بیچ — دیا — اور وہ — اس — میں — سے بے رغبت — تھے۔
۳۔ عملی سبق: اللہ — جسے — نیچا دکھائے — اسے بلند — کر سکتا ہے؛ صبر — اور — توکل — سے کام — لو۔"""
),
}
